css:
.cscall-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #0a1628 0%, #0f2541 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e2e8f0;
}

.cscall-sim-container * { box-sizing: border-box; }

.cscall-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(8, 28, 51, 0.7);
    border: 1px solid #1e3a5c;
    border-left: 4px solid #06b6d4;
    border-radius: 8px;
    padding: 22px 28px;
    margin-bottom: 20px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
}
.cscall-sim-header h1 {
    color: #f8fafc;
    font-size: 1.6rem;
    margin: 0 0 4px 0;
    font-weight: 700;
    letter-spacing: -0.01em;
}
.cscall-sim-subtitle {
    color: #94a3b8;
    font-size: 0.78rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.cscall-sim-header-right { text-align: right; }
.cscall-sim-clock-label {
    color: #64748b;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 4px;
}
.cscall-sim-clock {
    font-size: 2rem;
    font-weight: 700;
    color: #f59e0b;
    font-variant-numeric: tabular-nums;
    line-height: 1;
}

.cscall-sim-period-bar {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 22px;
    padding: 12px 18px;
    background: rgba(15, 37, 65, 0.6);
    border-radius: 6px;
    border: 1px solid #1e3a5c;
    flex-wrap: wrap;
}
.cscall-sim-period-pill {
    background: #06b6d4;
    color: #0a1628;
    padding: 6px 14px;
    border-radius: 999px;
    font-weight: 700;
    font-size: 0.82rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.cscall-sim-period-pill span { margin-right: 4px; }
.cscall-sim-round-name {
    color: #cbd5e1;
    font-size: 0.95rem;
    font-weight: 500;
}

.cscall-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.cscall-sim-status-card {
    background: #0f2541;
    border: 1px solid #1e3a5c;
    border-radius: 8px;
    padding: 18px 18px 16px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.18s ease, border-color 0.18s ease;
}
.cscall-sim-status-card:hover {
    transform: translateY(-2px);
    border-color: #2a5680;
}
.cscall-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
}
.cscall-sim-card-score::before { background: #06b6d4; }
.cscall-sim-card-total::before { background: linear-gradient(90deg, #06b6d4, #0ea5e9); }
.cscall-sim-card-queue::before { background: #f59e0b; }
.cscall-sim-card-csat::before { background: #10b981; }
.cscall-sim-card-band::before { background: #a78bfa; }

.cscall-sim-label {
    color: #64748b;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
}
.cscall-sim-value {
    font-size: 1.95rem;
    font-weight: 700;
    color: #f8fafc;
    line-height: 1.05;
    font-variant-numeric: tabular-nums;
}
.cscall-sim-card-score .cscall-sim-value { color: #06b6d4; }
.cscall-sim-card-queue .cscall-sim-value { color: #f59e0b; }
.cscall-sim-card-csat .cscall-sim-value { color: #10b981; }
.cscall-sim-card-band .cscall-sim-value {
    color: #a78bfa;
    font-size: 1.1rem;
    padding-top: 6px;
}
.cscall-sim-sub {
    color: #64748b;
    font-size: 0.7rem;
    margin-top: 4px;
}

.cscall-sim-briefing {
    background: rgba(15, 37, 65, 0.85);
    border: 1px solid #1e3a5c;
    border-left: 4px solid #f59e0b;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.cscall-sim-briefing-title {
    color: #f59e0b;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
    font-weight: 700;
}
.cscall-sim-briefing-text {
    color: #e2e8f0;
    font-size: 0.95rem;
    line-height: 1.65;
}
.cscall-sim-briefing-text strong { color: #fbbf24; }
.cscall-sim-briefing-text em { color: #94a3b8; font-style: italic; }

.cscall-sim-decisions {
    background: #0f2541;
    border: 1px solid #1e3a5c;
    border-radius: 8px;
    padding: 24px 26px;
    margin-bottom: 22px;
}
.cscall-sim-decisions h3 {
    color: #f8fafc;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1e3a5c;
}
.cscall-sim-decision { margin-bottom: 16px; }
.cscall-sim-decision label {
    display: block;
    color: #cbd5e1;
    font-size: 0.88rem;
    font-weight: 600;
    margin-bottom: 6px;
}
.cscall-sim-decisions select,
.cscall-sim-decisions input[type="text"],
.cscall-sim-decisions input[type="number"] {
    width: 100%;
    background: #0a1628;
    border: 1px solid #2a5680;
    color: #e2e8f0;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.15s ease;
}
.cscall-sim-decisions select:focus,
.cscall-sim-decisions input:focus {
    outline: none;
    border-color: #06b6d4;
    box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.15);
}
.cscall-sim-decisions select option {
    background: #0f2541;
    color: #e2e8f0;
    padding: 8px;
}

.cscall-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    align-items: center;
    flex-wrap: wrap;
}
.cscall-sim-actions .btn-primary {
    background: linear-gradient(135deg, #06b6d4, #0891b2);
    border: none;
    color: #0a1628;
    font-weight: 700;
    padding: 12px 24px;
    border-radius: 6px;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
    cursor: pointer;
}
.cscall-sim-actions .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(6, 182, 212, 0.3);
}
.cscall-sim-actions .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2a5680;
    color: #cbd5e1;
    padding: 10px 18px;
    border-radius: 6px;
    font-size: 0.85rem;
    cursor: pointer;
}
.cscall-sim-actions .btn-outline-secondary:hover {
    border-color: #06b6d4;
    color: #06b6d4;
}

.cscall-sim-feedback {
    background: rgba(6, 182, 212, 0.08);
    border: 1px solid rgba(6, 182, 212, 0.3);
    border-left: 4px solid #06b6d4;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 22px;
}
.cscall-sim-feedback-title {
    color: #06b6d4;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin-bottom: 10px;
}
.cscall-sim-feedback-text {
    color: #e2e8f0;
    font-size: 0.9rem;
    line-height: 1.7;
}

.cscall-sim-history,
.cscall-sim-chart-section {
    background: #0f2541;
    border: 1px solid #1e3a5c;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.cscall-sim-history h3,
.cscall-sim-chart-section h3 {
    color: #f8fafc;
    font-size: 1rem;
    font-weight: 700;
    margin: 0 0 16px 0;
}
.cscall-sim-history table {
    width: 100%;
    color: #cbd5e1;
    font-size: 0.88rem;
    border-collapse: collapse;
}
.cscall-sim-history table thead th {
    background: rgba(6, 182, 212, 0.08);
    color: #06b6d4;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 12px;
    border-bottom: 1px solid #1e3a5c;
    text-align: left;
}
.cscall-sim-history table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid #1e3a5c;
}
.cscall-sim-history table tbody tr:hover {
    background: rgba(6, 182, 212, 0.05);
}

.cscall-sim-chart {
    height: 280px;
    position: relative;
}

@media (max-width: 768px) {
    .cscall-sim-container { padding: 14px; }
    .cscall-sim-header { flex-direction: column; align-items: flex-start; gap: 12px; padding: 16px 18px; }
    .cscall-sim-header-right { text-align: left; }
    .cscall-sim-clock { font-size: 1.6rem; }
    .cscall-sim-status-cards { grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
    .cscall-sim-value { font-size: 1.5rem; }
    .cscall-sim-decisions, .cscall-sim-history, .cscall-sim-chart-section, .cscall-sim-briefing { padding: 16px 18px; }
}

/* FIX v1.1.0 - completion / shift-debrief screen */
.cscall-sim-completion { padding: 8px 4px; text-align: center; }
.cscall-sim-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.cscall-sim-completion-verdict { font-size: 24px; font-weight: 700; color: #0f172a; margin-bottom: 14px; }
.cscall-sim-completion-score { display: inline-flex; align-items: baseline; gap: 8px; padding: 8px 16px; background: #f1f5f9; border-radius: 8px; margin-bottom: 18px; }
.cscall-sim-completion-score span { font-size: 13px; color: #64748b; }
.cscall-sim-completion-score strong { font-size: 20px; color: #0f172a; }
.cscall-sim-completion-insights-heading { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: #64748b; margin-bottom: 8px; }
.cscall-sim-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 620px; text-align: left; }
.cscall-sim-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f8fafc; border-left: 3px solid #2563eb; border-radius: 4px; color: #1e293b; font-size: 14px; }

