                if (d.d3 === 'b') csatDelta -= 0.05;
                if (d.d5 === 'b') { queueDelta += 6; csatDelta -= 0.10; }
            } else if (period === 2) {
                queueDelta += 14;
                if (d.d1 === 'a' && d.d2 === 'a') { csatDelta += 0.15; queueDelta -= 5; }
                if (d.d3 === 'c') { csatDelta -= 0.20; queueDelta += 5; }
                if (d.d3 === 'a') csatDelta += 0.10;
                if (d.d4 === 'c') csatDelta -= 0.15;
                if (d.d4 === 'b') csatDelta -= 0.05;
                if (d.d5 === 'a') csatDelta += 0.05;
            } else if (period === 3) {
                queueDelta -= 8;
                if (d.d1 === 'a') csatDelta += 0.10;
                if (d.d1 === 'c') csatDelta -= 0.15;
                if (d.d3 === 'a') csatDelta += 0.05;
                if (d.d4 === 'a') csatDelta += 0.05;
                if (d.d2 === 'c') csatDelta -= 0.10;
            }

            state.domainState.totalScore += roundScore;
            state.domainState.queueLength = Math.max(0, state.domainState.queueLength + queueDelta);
            state.domainState.csat = Math.max(1, Math.min(5, state.domainState.csat + csatDelta));
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.queueHistory.push(state.domainState.queueLength);
            state.domainState.csatHistory.push(parseFloat(state.domainState.csat.toFixed(2)));

            var maxSoFar = (period === 1) ? 20 : (period === 2) ? 50 : 100;
            var pct = (state.domainState.totalScore / maxSoFar) * 100;
            var band;
            if (pct >= 90) band = window.mySimulation.t('band_distinction');
            else if (pct >= 75) band = window.mySimulation.t('band_credit');
            else if (pct >= 60) band = window.mySimulation.t('band_pass');
            else band = window.mySimulation.t('band_refer');
            state.domainState.band = band;

            // FIX v1.1.0 - expose a score the Express reporting layer reads.
            // results_utils.php::express_resolveDomainScore looks for
            // domainState.performance.overallScore first, then top-level `score`.
            // The original wrote neither (only totalScore), so the instructor panel
            // rendered an empty "-". totalScore is 0-100 by design (max 100 at R3).
            state.domainState.score = state.domainState.totalScore;
            state.domainState.performance = { overallScore: state.domainState.totalScore, grade: this._grade(pct) };

            var feedback = this._buildFeedback(period, d, roundScore);
            state.domainState.feedbackText = feedback;

            var self = this;
            setTimeout(((__eqilNext) => function () {
                self._updateRoundUI({ currentPeriod: __eqilNext });
                self._showFeedback(feedback);
            })(state.currentPeriod + 1), 300);

            return {
                period: period,
                roundScore: roundScore,
                cumulativeScore: state.domainState.totalScore,
                queue: state.domainState.queueLength,
                csat: parseFloat(state.domainState.csat.toFixed(2)),
                band: band
            };
        }

        _buildFeedback(period, d, roundScore) {
