                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r1_d1_a'));
                else if (d.d1 === 'b') lines.push('⚠ ' + t('fb_r1_d1_b'));
                else lines.push('✗ ' + t('fb_r1_d1_c'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r1_d2_a'));
                else if (d.d2 === 'b') lines.push('⚠ ' + t('fb_r1_d2_b'));
                else lines.push('✗ ' + t('fb_r1_d2_c'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r1_d3_a'));
                else if (d.d3 === 'b') lines.push('✗ ' + t('fb_r1_d3_b'));
                else lines.push('⚠ ' + t('fb_r1_d3_c'));

                if (d.d5 === 'b') lines.push('✗ ' + t('fb_r1_d5_b'));
                else lines.push('✓ ' + t('fb_r1_d5_a'));
            } else if (period === 2) {
                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r2_d1_a'));
                else lines.push('⚠ ' + t('fb_r2_d1_other'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r2_d2_a'));
                else lines.push('⚠ ' + t('fb_r2_d2_other'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r2_d3_a'));
                else if (d.d3 === 'b') lines.push('⚠ ' + t('fb_r2_d3_b'));
                else lines.push('✗ ' + t('fb_r2_d3_c'));

                if (d.d4 === 'a') lines.push('✓ ' + t('fb_r2_d4_a'));
                else if (d.d4 === 'b') lines.push('⚠ ' + t('fb_r2_d4_b'));
                else lines.push('✗ ' + t('fb_r2_d4_c'));

                if (d.d5 === 'a') lines.push('✓ ' + t('fb_r2_d5_a'));
                else lines.push('⚠ ' + t('fb_r2_d5_other'));
            } else if (period === 3) {
                if (d.d1 === 'a') lines.push('✓ ' + t('fb_r3_d1_a'));
                else lines.push('✗ ' + t('fb_r3_d1_other'));

                if (d.d2 === 'a') lines.push('✓ ' + t('fb_r3_d2_a'));
                else lines.push('⚠ ' + t('fb_r3_d2_other'));

                if (d.d3 === 'a') lines.push('✓ ' + t('fb_r3_d3_a'));
                else if (d.d3 === 'b') lines.push('⚠ ' + t('fb_r3_d3_b'));
                else lines.push('✗ ' + t('fb_r3_d3_c'));

                if (d.d4 === 'a') lines.push('✓ ' + t('fb_r3_d4_a'));
                else lines.push('⚠ ' + t('fb_r3_d4_other'));

                if (d.d5 === 'a') lines.push('✓ ' + t('fb_r3_d5_a'));
                else lines.push('✗ ' + t('fb_r3_d5_other'));
            }
            return lines.join('<br>');
        }

        _showFeedback(text) {
            var panel = document.getElementById('feedbackPanel');
            var fbText = document.getElementById('feedbackText');
            if (panel && fbText) {
                fbText.innerHTML = text;
                panel.style.display = 'block';
            }
        }

        _updateRoundUI(state) {
            var period = state.currentPeriod || 1;
            if (period > 3) period = 3;
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };

            var clockEl = document.getElementById('incidentClock');
            if (clockEl) clockEl.textContent = TIMES[period - 1];

            var roundNameEl = document.getElementById('roundName');
            if (roundNameEl) roundNameEl.textContent = '— ' + t('r' + period + '_name');

            var briefingTitleEl = document.getElementById('briefingTitle');
            var briefingTextEl = document.getElementById('briefingText');
            if (briefingTitleEl) briefingTitleEl.textContent = t('r' + period + '_brief_title');
            if (briefingTextEl) briefingTextEl.innerHTML = t('r' + period + '_brief');

            for (var i = 1; i <= 5; i++) {
                var labelEl = document.getElementById('d' + i + 'Label');
                var selectEl = document.getElementById('d' + i + 'Input');
                if (labelEl) labelEl.textContent = t('r' + period + '_d' + i + '_label');
                if (selectEl) {
                    selectEl.innerHTML = '';
                    var optKeys = ['a', 'b', 'c'];
                    for (var j = 0; j < optKeys.length; j++) {
                        var k = optKeys[j];
                        var optKey = 'r' + period + '_d' + i + '_' + k;
                        var optText = t(optKey);
                        if (optText === optKey) continue;
                        var opt = document.createElement('option');
                        opt.value = k;
                        opt.textContent = optText;
                        selectEl.appendChild(opt);
                    }
                    selectEl.value = 'a';
                }
            }
        }

