        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
        }

        _grade(pct) {
            if (pct >= 90) return 'A';
            if (pct >= 75) return 'B';
            if (pct >= 60) return 'C';
            return 'D';
        }

        getPerformanceSummary(history) {
            var t = this._t();
            var periods = history ? history.length : 0;
            if (!periods) return { totalPeriods: 0 };
            var totalScore = history.reduce(function (s, r) { return s + ((r.results && r.results.roundScore) || 0); }, 0);
            var avgScore = totalScore / periods;
            var verdictKey = 'perf_refer', insightKey = 'summary_refer';
            if (totalScore >= 90) { verdictKey = 'perf_distinction'; insightKey = 'summary_distinction'; }
            else if (totalScore >= 75) { verdictKey = 'perf_credit'; insightKey = 'summary_credit'; }
            else if (totalScore >= 60) { verdictKey = 'perf_pass'; insightKey = 'summary_pass'; }
            return {
                totalPeriods: periods,
                totalScore: totalScore,
                avgScore: avgScore,
                overallScore: totalScore,
                performance: t(verdictKey),
                verdictKey: verdictKey,
                insights: [t(insightKey)]
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                      : (typeof summary.totalScore === 'number') ? summary.totalScore : 0;
            var verdict = summary.performance || t('perf_refer');
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cscall-sim-completion">'
                +   '<div class="cscall-sim-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cscall-sim-completion-verdict">' + verdict + '</div>'
                +   '<div class="cscall-sim-completion-score"><span>' + t('comp_score_label') + '</span>'
                +     '<strong>' + score + '/100</strong></div>'
                +   '<div class="cscall-sim-completion-insights-heading">' + t('comp_insights_heading') + '</div>'
                +   '<ul class="cscall-sim-completion-insights">' + items + '</ul>'
                + '</div>';
        }

